prologue:
static MOD_UNUSED int config_has(const char* name) {
    return API->config != 0 && API->config->Has(SELF, name) != 0;
}

static MOD_UNUSED float config_number(const char* name) {
    return API->config != 0 ? API->config->GetNumber(SELF, name, 0.0f) : 0.0f;
}

static MOD_UNUSED const char* config_text(const char* name) {
    return API->config != 0 ? API->config->GetText(SELF, name, "") : "";
}

static MOD_UNUSED int config_text_is(const char* name, const char* text) {
    return strcmp(config_text(name), text) == 0;
}

static MOD_UNUSED int config_count(void) {
    return API->config != 0 ? API->config->Count(SELF) : 0;
}

static MOD_UNUSED const char* config_name_at(int index) {
    const char* name = API->config != 0 ? API->config->NameAt(SELF, index) : 0;
    return name != 0 ? name : "";
}

/* Get answers into a struct whose structSize the caller fills in first */
static MOD_UNUSED int config_key(const char* name, AmodConfigKey* key) {
    if (API->config == 0) return 0;
    memset(key, 0, sizeof *key);
    key->structSize = sizeof *key;
    return API->config->Get(SELF, name, key);
}

static MOD_UNUSED int config_flag(const char* name, unsigned int flag) {
    AmodConfigKey key;
    if (config_key(name, &key) == 0) return 0;
    return (key.flags & flag) != 0;
}

static MOD_UNUSED const char* config_fallback(const char* name) {
    AmodConfigKey key;
    if (config_key(name, &key) == 0 || key.fallback == 0) return "";
    return key.fallback;
}

static MOD_UNUSED int config_changed(const char* name) {
    AmodConfigKey key;
    if (config_key(name, &key) == 0) return 0;
    return key.value != 0 && key.fallback != 0 && strcmp(key.value, key.fallback) != 0;
}

/* Setting a key the game does not have does nothing, so a missing one is added first */
static MOD_UNUSED void config_set_text(const char* name, const char* value) {
    if (API->config == 0) return;
    if (API->config->SetText(SELF, name, value) == 0)
        API->config->Add(SELF, name, value, AMOD_CONFIG_SAVED);
}

static MOD_UNUSED void config_set_number(const char* name, float value) {
    char text[32];
    if (API->config == 0) return;
    if (API->config->SetNumber(SELF, name, value) != 0) return;
    sprintf(text, "%g", (double)value);
    API->config->Add(SELF, name, text, AMOD_CONFIG_SAVED);
}

/* An empty path means the file the game itself writes */
static MOD_UNUSED void config_save(const char* path) {
    if (API->config != 0) API->config->Save(SELF, path[0] != 0 ? path : 0);
}

static MOD_UNUSED void config_restore(const char* name) {
    AmodConfigKey key;
    if (config_key(name, &key) == 0 || key.fallback == 0) return;
    API->config->SetText(SELF, name, key.fallback);
}
